<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$supplier=(int)$_POST['supplier_id'];$paid=max(0,(float)$_POST['paid']);$items=json_decode((string)($_POST['items_json']??'[]'),true);if(!$supplier)throw new RuntimeException('Select a supplier.');if(!is_array($items)||!count($items))throw new RuntimeException('Add at least one medicine.');$clean=[];$total=0.0;foreach($items as $i=>$row){$mid=(int)($row['medicine_id']??0);$boxes=max(0,(int)($row['boxes']??0));$strips=max(0,(int)($row['strips']??0));$tabs=max(0,(int)($row['tablets']??0));$m=$db->prepare('SELECT * FROM medicines WHERE id=? AND active=1');$m->execute([$mid]);$med=$m->fetch();if(!$med)throw new RuntimeException('Medicine not found on line '.($i+1).'.');$qty=$boxes*(int)$med['strips_per_box']*(int)$med['units_per_strip']+$strips*(int)$med['units_per_strip']+$tabs;if($qty<1)throw new RuntimeException('Enter quantity for '.($med['name']??('line '.($i+1))).'.');$cost=max(0,(float)($row['unit_cost']??0));$line=$qty*$cost;$total+=$line;$clean[]=['medicine'=>$med,'boxes'=>$boxes,'strips'=>$strips,'tablets'=>$tabs,'qty'=>$qty,'cost'=>$cost,'total'=>$line,'batch'=>trim((string)($row['batch_no']??'')),'expiry'=>trim((string)($row['expiry_date']??''))];}$paid=min($total,$paid);$db->beginTransaction();$invoice='PUR-'.date('YmdHis').'-'.random_int(10,99);$db->prepare('INSERT INTO purchases(invoice_no,supplier_id,subtotal,paid) VALUES(?,?,?,?)')->execute([$invoice,$supplier,$total,$paid]);$pid=(int)$db->lastInsertId();foreach($clean as $r){$batch=$r['batch']!==''?$r['batch']:'AUTO-'.$invoice.'-'.($r['medicine']['id']);$expiry=$r['expiry']!==''?$r['expiry']:null;$db->prepare('INSERT INTO batches(medicine_id,batch_no,expiry_date,units_received,units_remaining,purchase_unit_cost) VALUES(?,?,?,?,?,?)')->execute([(int)$r['medicine']['id'],$batch,$expiry,$r['qty'],$r['qty'],$r['cost']]);$bid=(int)$db->lastInsertId();$db->prepare('INSERT INTO purchase_items(purchase_id,medicine_id,batch_id,quantity_units,unit_cost,line_total) VALUES(?,?,?,?,?,?)')->execute([$pid,(int)$r['medicine']['id'],$bid,$r['qty'],$r['cost'],$r['total']]);$db->prepare("INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,reference_id,note) VALUES(?,?, 'purchase',?,?,?)")->execute([(int)$r['medicine']['id'],$bid,$r['qty'],$pid,'Purchase '.$invoice]);}$db->prepare('UPDATE suppliers SET balance=balance+? WHERE id=?')->execute([$total-$paid,$supplier]);$db->commit();audit_log('purchase_created','Purchase '.$invoice.' · '.count($clean).' medicines · Rs. '.number_format($total,2));header('Location: purchases.php?saved=1');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$suppliers=$db->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();$meds=$db->query('SELECT * FROM medicines WHERE active=1 ORDER BY name')->fetchAll();$purchases=$db->query('SELECT p.*,s.name supplier FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.id DESC LIMIT 100')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Purchases · <?=e(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>.purchase-toolbar{display:flex;gap:10px;align-items:end;margin-bottom:14px}.purchase-table{width:100%;border-collapse:collapse}.purchase-table th,.purchase-table td{padding:9px;border-bottom:1px solid #edf0f5;vertical-align:middle}.purchase-table input,.purchase-table select{width:100%;padding:8px}.purchase-table .med-search{min-width:190px}.purchase-table .qty{width:75px}.remove-line{border:0;background:#fff;color:#c23838;font-size:22px;cursor:pointer}.purchase-summary{display:flex;justify-content:flex-end;gap:28px;align-items:center;margin-top:18px;font-size:15px}.purchase-summary strong{font-size:24px}.add-line{background:#eef3ff;color:#2154b7}.medicine-options{position:relative}.suggestions{position:absolute;z-index:30;left:0;right:0;top:100%;background:#fff;border:1px solid #dce3ee;border-radius:9px;box-shadow:0 10px 24px rgba(20,33,61,.15);display:none;max-height:300px;overflow:auto}.suggestions button{display:block;width:100%;padding:10px;text-align:left;border:0;border-bottom:1px solid #edf0f5;background:#fff;cursor:pointer}.suggestions button:hover{background:#f4f7ff}.suggestions small{display:block;color:#718096}.medicine-count{font-size:12px;color:#718096;margin-top:4px}@media(max-width:900px){.purchase-table{display:block;overflow-x:auto}.purchase-toolbar{flex-direction:column;align-items:stretch}.purchase-summary{justify-content:space-between}}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=e(current_user()['username']??'')?> · <?=e(ucfirst(current_user()['role']??''))?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">PURCHASING</div><h1>Purchases</h1><p>Add multiple medicines to one supplier invoice and receive them all at once.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Purchase saved and all stock lines added.</div><?php endif;?><section class="panel"><h2>New Purchase</h2><form method="post" id="purchaseForm"><div class="purchase-toolbar"><label style="flex:1">Supplier<select name="supplier_id" id="supplier" required><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><button type="button" class="btn add-line" id="addLine">+ Add Medicine <span class="shortcut">F2</span></button></div><div style="overflow-x:auto"><table class="purchase-table"><thead><tr><th>Medicine</th><th>Batch</th><th>Expiry</th><th>Boxes</th><th>Strips</th><th>Loose</th><th>Cost / tablet</th><th>Line Total</th><th></th></tr></thead><tbody id="lines"></tbody></table></div><input type="hidden" name="items_json" id="itemsJson"><div class="purchase-summary"><span>Total: <strong>Rs. <span id="grandTotal">0.00</span></strong></span><label>Paid now <input id="paid" type="number" name="paid" step="0.01" min="0" value="0"></label><button class="btn" type="submit">Save Purchase & Add All Stock <span class="shortcut">Ctrl+Enter</span></button></div></form></section><section class="panel"><h2>Purchase History</h2><table><tr><th>Invoice</th><th>Supplier</th><th>Subtotal</th><th>Paid</th><th>Due</th><th>Date</th></tr><?php foreach($purchases as $p):?><tr><td><?=e($p['invoice_no'])?></td><td><?=e($p['supplier']??'—')?></td><td>Rs. <?=money((float)$p['subtotal'])?></td><td>Rs. <?=money((float)$p['paid'])?></td><td>Rs. <?=money(max(0,(float)$p['subtotal']-(float)$p['paid']))?></td><td><?=e($p['created_at'])?></td></tr><?php endforeach;?></table></section></main><script>const meds=<?=json_encode($meds,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const lines=document.getElementById('lines');let lineNo=0;function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function addLine(m=null){const id=lineNo++;const tr=document.createElement('tr');tr.dataset.line=id;tr.innerHTML=`<td><div class="medicine-options"><input class="med-search" data-field="medicine-search" autocomplete="off" placeholder="Click or type to choose medicine..." value="${m?esc(m.name):''}"><input type="hidden" data-field="medicine-id" value="${m?m.id:''}"><div class="suggestions"></div><div class="medicine-count">${meds.length} medicine${meds.length===1?'':'s'} available</div></div></td><td><input data-field="batch" placeholder="Optional"></td><td><input data-field="expiry" type="date"></td><td><input data-field="boxes" class="qty" type="number" min="0" value="0"></td><td><input data-field="strips" class="qty" type="number" min="0" value="0"></td><td><input data-field="tablets" class="qty" type="number" min="0" value="0"></td><td><input data-field="cost" class="qty" type="number" step="0.0001" min="0" value="0"></td><td><b>Rs. <span data-field="total">0.00</span></b></td><td><button type="button" class="remove-line" title="Remove line">×</button></td>`;lines.appendChild(tr);bindLine(tr);if(!m)tr.querySelector('[data-field="medicine-search"]').focus();return tr;}function bindLine(tr){const search=tr.querySelector('[data-field="medicine-search"]'),suggest=tr.querySelector('.suggestions');function renderSuggest(){const q=search.value.trim().toLowerCase();const found=(q?meds.filter(m=>(m.name+' '+(m.generic_name||'')+' '+(m.strength||'')+' '+(m.barcode||'')).toLowerCase().includes(q)):meds).slice(0,50);suggest.innerHTML=found.map(m=>`<button type="button" data-id="${m.id}"><b>${esc(m.name)}</b><small>${esc((m.generic_name||'')+' '+(m.strength||''))} · Barcode ${esc(m.barcode||'—')} · Cost Rs.${Number(m.purchase_price||0).toFixed(2)}</small></button>`).join('')||'<div style="padding:10px">No medicine found.</div>';suggest.style.display='block';suggest.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>selectMed(meds.find(m=>m.id==b.dataset.id)));}function selectMed(m){if(!m)return;tr.querySelector('[data-field="medicine-id"]').value=m.id;search.value=m.name;suggest.style.display='none';tr.querySelector('[data-field="cost"]').value=Number(m.purchase_price||0).toFixed(4);update();tr.querySelector('[data-field="boxes"]').focus();}search.addEventListener('input',renderSuggest);search.addEventListener('focus',renderSuggest);search.addEventListener('click',renderSuggest);search.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();const b=suggest.querySelector('button');if(b)b.focus();}else if(e.key==='Enter'){e.preventDefault();const b=suggest.querySelector('button');if(b)b.click();}});tr.querySelectorAll('input').forEach(x=>x.addEventListener('input',update));tr.querySelector('.remove-line').onclick=()=>{tr.remove();update();if(!lines.children.length)addLine();};suggest.addEventListener('keydown',e=>{if(e.key==='Escape'){suggest.style.display='none';search.focus();}});}function update(){let total=0;[...lines.children].forEach(tr=>{const mid=Number(tr.querySelector('[data-field="medicine-id"]').value),m=meds.find(x=>Number(x.id)===mid),boxes=Number(tr.querySelector('[data-field="boxes"]').value)||0,strips=Number(tr.querySelector('[data-field="strips"]').value)||0,tabs=Number(tr.querySelector('[data-field="tablets"]').value)||0,cost=Number(tr.querySelector('[data-field="cost"]').value)||0;const qty=m?boxes*Number(m.strips_per_box)*Number(m.units_per_strip)+strips*Number(m.units_per_strip)+tabs:0,line=qty*cost;total+=line;tr.querySelector('[data-field="total"]').textContent=line.toFixed(2);});document.getElementById('grandTotal').textContent=total.toFixed(2);}document.getElementById('addLine').onclick=()=>addLine();document.getElementById('purchaseForm').addEventListener('submit',e=>{const data=[];for(const tr of lines.children){const q=x=>tr.querySelector(`[data-field="${x}"]`).value;const mid=Number(q('medicine-id'));if(!mid){e.preventDefault();alert('Select a medicine on every line.');tr.querySelector('[data-field="medicine-search"]').focus();return;}const m=meds.find(x=>Number(x.id)===mid);const qty=(Number(q('boxes'))||0)*Number(m.strips_per_box)*Number(m.units_per_strip)+(Number(q('strips'))||0)*Number(m.units_per_strip)+(Number(q('tablets'))||0);if(qty<1){e.preventDefault();alert('Enter a quantity for '+m.name+'.');return;}data.push({medicine_id:mid,batch_no:q('batch'),expiry_date:q('expiry'),boxes:Number(q('boxes'))||0,strips:Number(q('strips'))||0,tablets:Number(q('tablets'))||0,unit_cost:Number(q('cost'))||0});}document.getElementById('itemsJson').value=JSON.stringify(data);});document.addEventListener('click',e=>{if(!e.target.closest('.medicine-options'))document.querySelectorAll('.suggestions').forEach(x=>x.style.display='none');});document.addEventListener('keydown',e=>{if(e.key==='F2'){e.preventDefault();addLine();}if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();document.getElementById('purchaseForm').requestSubmit();}});addLine();</script></body></html>